    Solve the lookup type from the lookup (e.g.: 'foobar__id__icontains').
    """
    lookup_splitted = lookup.split(LOOKUP_SEP)
    if self.annotations:
        annotation, expression_lookups = refs_expression(
            lookup_splitted, self.annotations
